import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { type NextRequest, NextResponse } from "next/server";
import type { Database } from "@/lib/database.types";

export async function GET(request: NextRequest) {
  const { searchParams, origin } = new URL(request.url);
  const code = searchParams.get("code");
  const rawNext = searchParams.get("next") ?? "/dashboard";
  // Prevent open redirect: only allow relative paths starting with /
  const next = rawNext.startsWith("/") && !rawNext.startsWith("//") ? rawNext : "/dashboard";

  if (code) {
    // Determine redirect URL
    const forwardedHost = request.headers.get("x-forwarded-host");
    const forwardedProto = request.headers.get("x-forwarded-proto") || "https";
    const isLocalEnv = process.env.NODE_ENV === "development";
    let redirectUrl: string;
    if (isLocalEnv) {
      redirectUrl = `${origin}${next}`;
    } else if (forwardedHost) {
      redirectUrl = `${forwardedProto}://${forwardedHost}${next}`;
    } else {
      redirectUrl = `${origin}${next}`;
    }

    const cookieStore = await cookies();
    const response = NextResponse.redirect(redirectUrl);
    const THIRTY_DAYS_IN_SECONDS = 60 * 60 * 24 * 30; // 30 days (1 month persistent session)

    const supabase = createServerClient<Database>(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
      {
        cookies: {
          getAll() {
            return cookieStore.getAll();
          },
          setAll(cookiesToSet) {
            cookiesToSet.forEach(({ name, value, options }) => {
              const isDeleting = value === "" || options?.maxAge === 0;
              const opts = {
                ...options,
                maxAge: isDeleting ? 0 : (options?.maxAge ?? THIRTY_DAYS_IN_SECONDS),
                sameSite: options?.sameSite ?? ("lax" as const),
                path: options?.path ?? "/",
              };
              response.cookies.set(name, value, opts);
            });
          },
        },
      }
    );

    const { error } = await supabase.auth.exchangeCodeForSession(code);

    if (!error) {
      const AUTHORIZED_EMAIL = "iamsaran.ai@gmail.com";
      const ACCESS_RESTRICTED_MSG = "Access Restricted. arthaX is operating in private single-user mode for authorized accounts only.";

      const { data: { user } } = await supabase.auth.getUser();
      if (user && user.email?.trim().toLowerCase() !== AUTHORIZED_EMAIL) {
        await supabase.auth.signOut();
        return NextResponse.redirect(`${origin}/login?error=${encodeURIComponent(ACCESS_RESTRICTED_MSG)}`);
      }
      return response;
    } else {
      console.error("OAuth callback exchangeCodeForSession error:", error);
      return NextResponse.redirect(`${origin}/login?error=${encodeURIComponent("Auth error: " + error.message)}`);
    }
  }

  // If code exchange failed or no code present, redirect back to login
  const errParam = searchParams.get("error_description") || "Google authentication failed";
  return NextResponse.redirect(`${origin}/login?error=${encodeURIComponent(errParam)}`);
}
